Algorithm NoRain
  Dimension days[10] As Integer;
  For i <- 0 To 9 Do
    Read days[i];
  EndFor
  Define streak As Integer <- 0;
  Define longest As Integer <- 0;
  For Each rained In days Do
    If rained = 0 Then
      streak <- streak + 1;
      If streak > longest Then
        longest <- streak;
      EndIf
    Else
      streak <- 0;
    EndIf
  EndFor
  Write longest;
EndAlgorithm
